"""Idempotent patch for the vendored sczhou/CodeFormer checkout, applied
by scripts/setup_windows.ps1 right after cloning.

CodeFormer bundles its own copy of `basicsr` (vendor/CodeFormer/basicsr/,
independent of the pip-installed `basicsr` GFPGAN uses). That local
package's `__init__.py` imports `from .version import __gitsha__,
__version__`, but `version.py` is only generated by `setup.py`'s
`write_version_py()` when the package is actually built/installed — which
we never do (CodeFormer is used via sys.path insertion, not pip install,
same pattern as scripts/wav2lip_runner.py / scripts/sadtalker_runner.py).
Without it, `import basicsr` fails with
`ModuleNotFoundError: No module named 'basicsr.version'`.

Usage:
    python vendor/patches/patch_codeformer.py <vendor-CodeFormer-checkout-dir>
"""

from __future__ import annotations

import sys
from pathlib import Path

VERSION_FILE_CONTENT = """# GENERATED VERSION FILE (written by vendor/patches/patch_codeformer.py,
# since CodeFormer is used via sys.path, never `pip install`'d, so its own
# setup.py-generated version.py never gets created otherwise)
__version__ = '1.3.2'
__gitsha__ = 'unknown'
version_info = (1, 3, 2)
"""


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: patch_codeformer.py <vendor-CodeFormer-checkout-dir>", file=sys.stderr)
        return 1
    root = Path(sys.argv[1])
    version_path = root / "basicsr" / "version.py"
    if version_path.exists():
        print("basicsr/version.py: already present, skipping")
        return 0
    if not version_path.parent.exists():
        raise RuntimeError(f"{version_path.parent} does not exist; CodeFormer repo layout may have changed")
    version_path.write_text(VERSION_FILE_CONTENT, encoding="utf-8")
    print(f"basicsr/version.py: created {version_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
